#include <string>
using namespace std;

int main() {
    string s;
    while (cin >> s) {
        int n = s.size();
        int ans = 0, current_length = 1;
        for (int i = 1; i < n; i++) {
            if (s[i] == s[i - 1]) {
                current_length++;
            } else {
                if (s[i - 1] == 'O' && i - 1 > 0 && s[i] != 'O') {
                    int left_length = 0, right_length = 0;
                    for (int j = i - 1; j >= 0 && s[j] == s[i - 1]; j--) left_length++;
                    for (int j = i; j < n && s[j] == s[i]; j++) right_length++;
                    if (right_length >= left_length && left_length > 0) {
                        ans = max(ans, left_length);
                    }
                }
                current_length = 1; // reset for new character
            }
        }
        cout << ans << endl;
    }
}

